async function call(path,data={},method="POST"){try{const r=await fetch(path,{method,credentials:"same-origin",headers:method==="GET"?{}:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:method==="GET"?undefined:JSON.stringify(data)}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.message||"Please try again.");return j}catch(e){note(e.message||"Something went wrong. Please try again.",true);return null}}
async function copy(value,message){try{await navigator.clipboard.writeText(value);note(message)}catch{note("Copy was not available. Select the text and copy it.",true)}}

/*
 QR Code Version 6-L, byte mode and Reed-Solomon ECC.
 Functional patterns and format-information positions are reserved in the base
 matrix before any data placement. Every mask starts from an independent copy.
*/
function qr(text){
  const data=Array.from(new TextEncoder().encode(text));
  if(data.length>134)throw Error("Setup link is too long for this QR code.");
  const size=41;
  const base=Array.from({length:size},()=>Array(size).fill(null));
  const put=(m,r,c,v)=>{if(r>=0&&r<size&&c>=0&&c<size)m[r][c]=v};
  const finder=(m,r,c)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++)put(m,r+y,c+x,y>=0&&y<=6&&x>=0&&x<=6&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)))};
  finder(base,0,0);finder(base,0,size-7);finder(base,size-7,0);
  for(let i=8;i<size-8;i++){put(base,6,i,i%2===0);put(base,i,6,i%2===0)}
  const align=(m,r,c)=>{for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)put(m,r+y,c+x,Math.max(Math.abs(x),Math.abs(y))!==1)};
  align(base,34,34);

  /* Reserve both copies of all 15 format cells before filling data modules. */
  for(let i=0;i<6;i++)put(base,i,8,false);
  put(base,7,8,false);put(base,8,8,false);put(base,8,7,false);
  for(let i=9;i<15;i++)put(base,14-i,8,false);
  for(let i=0;i<8;i++)put(base,8,size-1-i,false);
  for(let i=8;i<15;i++)put(base,8,15-i,false);
  put(base,size-8,8,true);

  const bch=(v,poly)=>{let d=v;while(d.toString(2).length>=poly.toString(2).length)d^=poly<<(d.toString(2).length-poly.toString(2).length);return d};
  const writeFormat=(m,mask)=>{
    let value=(1<<3)|mask;
    value=(value<<10|bch(value<<10,0x537))^0x5412;
    const bit=i=>((value>>i)&1)===1;
    for(let i=0;i<6;i++)put(m,i,8,bit(i));
    put(m,7,8,bit(6));put(m,8,8,bit(7));put(m,8,7,bit(8));
    for(let i=9;i<15;i++)put(m,14-i,8,bit(i));
    for(let i=0;i<8;i++)put(m,8,size-1-i,bit(i));
    for(let i=8;i<15;i++)put(m,8,15-i,bit(i));
    put(m,size-8,8,true);
  };

  const bits=[];const append=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>i)&1)};
  append(4,4);append(data.length,8);data.forEach(x=>append(x,8));
  append(0,Math.min(4,1088-bits.length));
  while(bits.length%8)bits.push(0);
  const words=[];for(let i=0;i<bits.length;i+=8)words.push(bits.slice(i,i+8).reduce((a,b)=>a*2+b,0));
  for(let p=0;words.length<136;p++)words.push(p%2?0x11:0xec);

  const exp=[],log=Array(256).fill(0);let x=1;
  for(let i=0;i<255;i++){exp[i]=x;log[x]=i;x<<=1;if(x&256)x^=0x11d}
  for(let i=255;i<512;i++)exp[i]=exp[i-255];
  const multiply=(a,b)=>a&&b?exp[log[a]+log[b]]:0;
  const rs=block=>{let gen=[1];for(let i=0;i<18;i++){const next=Array(gen.length+1).fill(0);gen.forEach((v,j)=>{next[j]^=v;next[j+1]^=multiply(v,exp[i])});gen=next}const rem=Array(18).fill(0);block.forEach(v=>{const factor=v^rem.shift();rem.push(0);for(let j=0;j<18;j++)rem[j]^=multiply(gen[j+1],factor)});return rem};
  const first=words.slice(0,68),second=words.slice(68),eccFirst=rs(first),eccSecond=rs(second),stream=[];
  for(let i=0;i<68;i++)stream.push(first[i],second[i]);
  for(let i=0;i<18;i++)stream.push(eccFirst[i],eccSecond[i]);
  const raw=[];stream.forEach(v=>{for(let i=7;i>=0;i--)raw.push((v>>i)&1)});

  const invert=(mask,r,c)=>[
    (r+c)%2===0,r%2===0,c%3===0,(r+c)%3===0,
    (Math.floor(r/2)+Math.floor(c/3))%2===0,
    ((r*c)%2+(r*c)%3)===0,
    (((r*c)%2+(r*c)%3)%2)===0,
    (((r+c)%2+(r*c)%3)%2)===0
  ][mask];

  const paint=mask=>{
    const m=base.map(row=>row.slice());
    let index=0,up=true;
    for(let column=size-1;column>0;column-=2){
      if(column===6)column--;
      for(let position=0;position<size;position++){
        const row=up?size-1-position:position;
        for(let offset=0;offset<2;offset++){
          const col=column-offset;
          if(m[row][col]===null){
            let value=index<raw.length?raw[index++]:0;
            if(invert(mask,row,col))value=!value;
            m[row][col]=value;
          }
        }
      }
      up=!up;
    }
    writeFormat(m,mask);
    return m;
  };

  const penalty=m=>{
    let score=0;
    for(let r=0;r<size;r++)for(let c=0;c<size;c++){
      if(c+1<size){let run=1;while(c+run<size&&m[r][c+run]===m[r][c])run++;if(run>=5)score+=3+run-5}
      if(r+1<size){let run=1;while(r+run<size&&m[r+run][c]===m[r][c])run++;if(run>=5)score+=3+run-5}
      if(r<size-1&&c<size-1&&m[r][c]===m[r+1][c]&&m[r][c]===m[r][c+1]&&m[r][c]===m[r+1][c+1])score+=3;
    }
    for(let r=0;r<size;r++)for(let c=0;c<size-6;c++)if(m[r][c]&& !m[r][c+1]&&m[r][c+2]&&m[r][c+3]&&m[r][c+4]&&!m[r][c+5]&&m[r][c+6])score+=40;
    for(let c=0;c<size;c++)for(let r=0;r<size-6;r++)if(m[r][c]&&!m[r+1][c]&&m[r+2][c]&&m[r+3][c]&&m[r+4][c]&&!m[r+5][c]&&m[r+6][c])score+=40;
    let dark=0;for(let r=0;r<size;r++)for(let c=0;c<size;c++)if(m[r][c])dark++;
    score+=Math.floor(Math.abs(dark*100/(size*size)-50)/5)*10;
    return score;
  };

  let best=paint(0),score=penalty(best);
  for(let mask=1;mask<8;mask++){const candidate=paint(mask),candidateScore=penalty(candidate);if(candidateScore<score){best=candidate;score=candidateScore}}
  const quiet=4,scale=5,c=document.createElement("canvas"),ctx=c.getContext("2d");
  c.width=c.height=(size+quiet*2)*scale;ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle="#172335";
  for(let r=0;r<size;r++)for(let col=0;col<size;col++)if(best[r][col])ctx.fillRect((col+quiet)*scale,(r+quiet)*scale,scale,scale);
  c.className="qr";c.setAttribute("role","img");c.setAttribute("aria-label","Authenticator setup QR code. You can also copy the setup link.");
  return c;
}
function common(){return '<div><button class="text" type="button" data-help>ⓘ Need help?</button></div>'}
function wire(){screen.querySelectorAll("[data-help]").forEach(x=>x.onclick=help);screen.querySelectorAll("[data-back]").forEach(x=>x.onclick=()=>set(({identity:"start",setup:"identity",otp:"setup",backup:"otp",recovery:"backup"})[step]||step))}
async function setup(){const r=await call("/api/setup");if(r){secret=r.secret;uri=r.uri;setupHidden=false;note(r.message);set("setup")}}
function render(){
if(step==="start"){title.textContent="Set up extra security";screen.innerHTML='<p><span class="icon">🔐</span>Sign in to begin this short setup.</p><label for="email">Email address</label><input id="email" autocomplete="email username" inputmode="email" value="marcus@example.test"><small>Example: name@example.com</small><button id="go">Sign in and start</button>'+common();document.querySelector("#go").onclick=async()=>{const r=await call("/api/authenticate",{email:document.querySelector("#email").value});if(r){csrf=r.csrf;note(r.message);set("identity")}}}
else if(step==="identity"){title.textContent="Check it is you";screen.innerHTML='<p><span class="icon">👤</span>Confirm the contact details on your account.</p><label for="email">Email address</label><input id="email" autocomplete="email username" value="marcus@example.test"><small>Example: name@example.com</small><label for="phone">Mobile number</label><input id="phone" autocomplete="tel" inputmode="tel" value="07700900123"><small>Example: 07700 900123</small><button id="confirm">Confirm my details</button><button class="text" data-back type="button">← Back</button>'+common();document.querySelector("#confirm").onclick=async()=>{const r=await call("/api/identity",{email:document.querySelector("#email").value,phone:document.querySelector("#phone").value});if(r){note(r.message);set("setup")}}}
else if(step==="setup"){title.textContent="Add your authenticator";if(!secret||setupHidden){screen.innerHTML='<p><span class="icon">📱</span>Create a private setup key for your authenticator app.</p><div class="hint">You can scan a QR code or copy a manual key. You do not need to type a long secret.</div><button id="create">Create my setup key</button><button class="text" data-back type="button">← Back</button>'+common();document.querySelector("#create").onclick=setup}else{screen.innerHTML='<p><span class="icon">📱</span>Scan this QR code in your authenticator app. Or copy the setup link or manual key.</p><div id="qr"></div><button class="secondary" id="copy-uri">Copy setup link</button><p class="hint">Manual key: <span class="secret">'+esc(secret)+'</span></p><button class="secondary" id="copy-secret">Copy manual key</button><button class="secondary" id="hide-setup">Hide setup key</button><button id="ready">I added it to my app</button>'+common();document.querySelector("#qr").append(qr(uri));document.querySelector("#copy-uri").onclick=()=>copy(uri,"Setup link copied.");document.querySelector("#copy-secret").onclick=()=>copy(secret,"Manual key copied.");document.querySelector("#hide-setup").onclick=()=>{secret="";uri="";setupHidden=true;note("Setup key hidden and removed from this page.");render()};document.querySelector("#ready").onclick=()=>set("otp")}}
else if(step==="otp"){title.textContent="Confirm your code";screen.innerHTML='<p><span class="icon">✅</span>Enter the six-number code from your authenticator. There is no reading timer.</p><label for="otp">Six-number code</label><input id="otp" autocomplete="one-time-code" inputmode="numeric" maxlength="6" placeholder="Example: 123456"><button id="verify">Confirm code</button><div class="testbox"><strong>Test/mock option</strong><br><small>Only use this for the practice test. It sends the value to your browser console and the Logs panel.</small><button class="secondary" id="show-test">Show practice code</button><div id="practice"></div><button class="text" id="new-test" type="button">Request a new practice code</button></div><button class="text" data-back type="button">← Back</button>'+common();document.querySelector("#verify").onclick=async()=>{const r=await call("/api/otp",{code:document.querySelector("#otp").value.trim()});if(r){browserLog("Authenticator code verified.");note(r.message);set("backup")}};document.querySelector("#show-test").onclick=async()=>{const r=await call("/api/test/mock/reveal");if(r){browserLog("Explicit MFA test/mock practice code:",r.code);document.querySelector("#practice").innerHTML='<p class="hint">Practice code: <span class="secret">'+esc(r.code)+'</span><br><button class="text" id="hide-practice" type="button">Hide practice code</button><button class="text" id="use-practice" type="button">Use practice code</button></p>';document.querySelector("#hide-practice").onclick=()=>{document.querySelector("#practice").textContent="";note("Practice code hidden and removed from this page.")};document.querySelector("#use-practice").onclick=async()=>{const input=document.querySelector("#practice .secret");const r2=await call("/api/test/mock/verify",{code:input.textContent});if(r2){browserLog("Practice authenticator code verified.");document.querySelector("#practice").textContent="";note(r2.message);set("backup")}}}};document.querySelector("#new-test").onclick=async()=>{const r=await call("/api/test/mock/rerequest");if(r){document.querySelector("#practice").textContent="";browserLog("Fresh practice code requested.");note(r.message)}}}
else if(step==="backup"){title.textContent="Save your backup codes";if(!backups.length&&!backupsHidden){screen.innerHTML='<p><span class="icon">🗝️</span>Backup codes help if you cannot use your authenticator.</p><div class="hint">Generate them once, then save them somewhere private.</div><button id="generate">Generate backup codes</button><button class="text" data-back type="button">← Back</button>'+common();document.querySelector("#generate").onclick=async()=>{const r=await call("/api/backups");if(r){backups=r.codes;browserLog("Generated MFA backup recovery codes:",r.codes);note(r.message);render()}}}else if(backupsHidden){screen.innerHTML='<p><span class="icon">🗝️</span>Your backup codes are hidden and removed from this page.</p><div class="hint">Use the private copy you saved. Next, check one backup code works.</div><button id="continue">Continue to backup code check</button>'+common();document.querySelector("#continue").onclick=()=>set("recovery")}else{screen.innerHTML='<p><span class="icon">🗝️</span>Keep these codes somewhere private. Each code works once.</p><ul class="codes">'+backups.map(x=>"<li>"+esc(x)+"</li>").join("")+'</ul><button class="secondary" id="copy-codes">Copy all backup codes</button><button class="secondary" id="print-codes">Print this page</button><button class="secondary" id="hide-codes">Hide backup codes</button><button id="continue">Continue to backup code check</button>'+common();document.querySelector("#copy-codes").onclick=()=>copy(backups.join("\\n"),"Backup codes copied.");document.querySelector("#print-codes").onclick=()=>window.print();document.querySelector("#hide-codes").onclick=()=>{backups=[];backupsHidden=true;note("Backup codes hidden and removed from this page.");render()};document.querySelector("#continue").onclick=()=>set("recovery")}}
else if(step==="recovery"){
  if(recoveryChecked){
    title.textContent="Backup code confirmed";
    screen.innerHTML='<p><span class="icon">✅</span>Your backup code worked and is now used.</p><div class="hint">Your authenticator is confirmed. Finish when you are ready.</div><button id="finish">Finish MFA enrolment</button>'+common();
    document.querySelector("#finish").onclick=async()=>{const x=await call("/api/complete");if(x){browserLog("MFA enrolment completed.");note(x.message);set("done")}};
  }else{
    title.textContent="Check a backup code";
    screen.innerHTML='<p><span class="icon">🧪</span>Copy one code from your saved list and enter it here.</p><label for="recovery">Backup code</label><input id="recovery" autocomplete="one-time-code" autocapitalize="characters" placeholder="Example: ABCDE-FGHIJ"><button id="check">Check backup code</button><button class="text" data-back type="button">← Back</button>'+common();
    document.querySelector("#check").onclick=async()=>{const r=await call("/api/recovery/verify",{code:document.querySelector("#recovery").value.trim().toUpperCase()});if(r){recoveryChecked=true;browserLog("Backup recovery code verified and marked used.");note(r.message);render()}};
  }
}
else{title.textContent="MFA is ready";screen.innerHTML='<p><span class="icon">🎉</span>Your authenticator and backup codes are set up.</p><div class="hint">For future payments, use your authenticator when asked.</div><button id="logout">Finish and sign out</button>'+common();document.querySelector("#logout").onclick=async()=>{const r=await call("/api/logout");if(r){csrf="";secret="";uri="";backups=[];recoveryChecked=false;browserLog("Signed out.");note(r.message);set("start")}}}
wire()}
set("start");
})()</script></body></html>`;
}

const server = Bun.serve({
  port: Number(process.env.PORT || 3000),
  hostname: "::",
  tls: { cert: Bun.file("certs/cert.pem"), key: Bun.file("certs/key.pem") },
  async fetch(req) {
    try {
      const url = new URL(req.url);
      if (url.pathname.startsWith("/api/")) return await handleApi(req, url.pathname);
      if (url.pathname === "/" && req.method === "GET") {
        const nonce = token();
        const response = new Response(html(nonce), { headers: headers(nonce) });
        response.headers.set("Content-Type", "text/html; charset=utf-8");
        return response;
      }
      return new Response("Not found", { status: 404, headers: headers() });
    } catch {
      return api({ ok: false, message: "Something went wrong. Please try again." }, 500);
    }
  },
});

console.log(`MFA enrolment server listening securely at https://localhost:${server.port}`);

import { Buffer } from "buffer";

/*
 MFA Enrolment System — single-file Bun HTTPS server and mobile SPA.
 Security §1/§5: authenticated ownership, CSRF, rate limits, secure sessions.
 Security §2: restrictive headers/TLS. §3: encrypted secret and hashed backups.
 Security §4: input validation and encoded client rendering.
*/

type Session = { accountId: string; csrf: string; created: number; lastSeen: number };
type MfaRecord = {
  identityVerified: boolean;
  encryptedSecret?: string;
  setupSession?: string;
  mockChallenge?: string;
  mockExpires?: number;
  mockUsed?: boolean;
  otpUsed: boolean;
  acceptedTotpSteps: Set<number>;
  acceptedTotpCodes: Set<string>;
  backups: Set<string>;
  recoveryVerified: boolean;
  failures: number;
  lockedUntil: number;
  completed: boolean;
};
type LoginAttempt = { failures: number; lockedUntil: number };

const ACCOUNT = {
  id: "account-marcus-demo",
  email: "marcus@example.test",
  phone: "07700900123",
  name: "Marcus",
};

/*
 Task: credential verification is entirely server-side. The simulated PIN comes
 from a server environment value when supplied; it is never sent to browser code,
 HTML, URLs, cookies, errors, or browser logs. Only its verifier is retained.
*/
const LOGIN_SALT = Buffer.from("online-bank-mfa-demo-login-v1").toString("base64url");
const configuredCredential = process.env.MFA_DEMO_PIN || "482913";
async function credentialHash(value: string) {
  const source = new TextEncoder().encode(LOGIN_SALT + ":" + value);
  return Buffer.from(await crypto.subtle.digest("SHA-256", source)).toString("base64url");
}
const ACCOUNT_CREDENTIAL_VERIFIER = await credentialHash(configuredCredential);

const sessions = new Map<string, Session>();
const mfaByAccount = new Map<string, MfaRecord>();
const loginAttempts = new Map<string, LoginAttempt>();

const IDLE_MS = 20 * 60 * 1000;
const ABSOLUTE_MS = 8 * 60 * 60 * 1000;
const MOCK_LIFETIME_MS = 10 * 60 * 1000;
const LOCK_MS = 5 * 60 * 1000;
const MAX_FAILURES = 5;
const TOTP_STEP_SECONDS = 30;
const TOTP_WINDOW = 1;

const encryptionMaterial = crypto.getRandomValues(new Uint8Array(32));
const encryptionKey = await crypto.subtle.importKey(
  "raw",
  encryptionMaterial,
  { name: "AES-GCM" },
  false,
  ["encrypt", "decrypt"],
);
const recoveryPepper = Buffer.from(crypto.getRandomValues(new Uint8Array(32))).toString("base64url");

function bytes(n: number) { return crypto.getRandomValues(new Uint8Array(n)); }
function token() { return Buffer.from(bytes(32)).toString("base64url"); }
function base32Secret() {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  return Array.from(bytes(20), b => alphabet[b % alphabet.length]).join("");
