function recoveryCode() {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const raw = Array.from(bytes(10), b => alphabet[b % alphabet.length]).join("");
  return raw.slice(0, 5) + "-" + raw.slice(5);
