 const bch=(v,p)=>{let d=0,t=v;while(t){d++;t>>>=1}let pd=0,q=p;while(q){pd++;q>>>=1}while(d>=pd){v^=p<<(d-pd);d=0;t=v;while(t){d++;t>>>=1}}return v};
